CREATE TABLE t_auth_session (id BIGINT AUTO_INCREMENT PRIMARY KEY,jti VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT NOT NULL,expires_at TIMESTAMP NOT NULL,revoked_at TIMESTAMP,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE t_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,nickname VARCHAR(50),avatar_url VARCHAR(500),current_user_character_id BIGINT,status TINYINT DEFAULT 1,deleted TINYINT DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE t_character (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,character_type TINYINT NOT NULL,name VARCHAR(80) NOT NULL,age SMALLINT,identity VARCHAR(200),core_personality VARCHAR(1000),current_goal VARCHAR(500),biography VARCHAR(5000),relationship_to_user VARCHAR(300),speaking_style VARCHAR(500),profile_config VARCHAR(10000),source_description VARCHAR(2000),generate_type TINYINT DEFAULT 0,visual_type TINYINT DEFAULT 0,avatar_id BIGINT,image_url VARCHAR(500),avatar_color VARCHAR(32),status TINYINT DEFAULT 1,deleted TINYINT DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE t_character_image_generation (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,character_id BIGINT,request_id VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,prompt VARCHAR(2000) NOT NULL,status VARCHAR(20) NOT NULL,image_path VARCHAR(500),image_url VARCHAR(500),confirmed_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_id));
CREATE TABLE t_avatar (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,name VARCHAR(50) NOT NULL,type TINYINT DEFAULT 1,gender TINYINT DEFAULT 2,base_model VARCHAR(100),model_url VARCHAR(500),thumbnail_url VARCHAR(500),appearance_config VARCHAR(4000),personality_id BIGINT,slogan VARCHAR(200),source_description VARCHAR(1000),generate_type TINYINT DEFAULT 0,generate_result VARCHAR(4000),template_id BIGINT,status TINYINT DEFAULT 1,deleted TINYINT DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE t_personality (id BIGINT AUTO_INCREMENT PRIMARY KEY,avatar_id BIGINT,name VARCHAR(64),template_type TINYINT,core_personality VARCHAR(512),identity VARCHAR(128),language_style VARCHAR(256),hobbies VARCHAR(512),status TINYINT DEFAULT 1,deleted TINYINT DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE t_chat_session (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,avatar_id BIGINT,character_id BIGINT,character_snapshot VARCHAR(10000),character_snapshot_version INT,personality_id BIGINT,personality_snapshot VARCHAR(4000),personality_snapshot_version INT,title VARCHAR(100),status TINYINT DEFAULT 1,deleted TINYINT DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE t_chat_message (id BIGINT AUTO_INCREMENT PRIMARY KEY,session_id BIGINT NOT NULL,request_id VARCHAR(64),role TINYINT NOT NULL,content VARCHAR(4000) NOT NULL,emotion VARCHAR(50),status TINYINT DEFAULT 2,error_code VARCHAR(50),error_message VARCHAR(500),deleted TINYINT DEFAULT 0,create_time TIMESTAMP,update_time TIMESTAMP,completion_time TIMESTAMP);
